{
  "root": "main_stack",
  "state": {
    "itinerary_data": [
      {
        "day": "Day 1: June 12, 2025",
        "time": "09:00 - 10:30",
        "event": "Keynote: The Future of Generative AI",
        "location": "Main Hall"
      },
      {
        "day": "Day 1: June 12, 2025",
        "time": "10:30 - 10:45",
        "event": "Transit Buffer",
        "location": "15 Minutes"
      },
      {
        "day": "Day 1: June 12, 2025",
        "time": "11:00 - 12:00",
        "event": "Workshop: Building Scalable Vector Databases",
        "location": "Room B"
      },
      {
        "day": "Day 1: June 12, 2025",
        "time": "12:00 - 14:00",
        "event": "Midday Break / Secondary Option: Ethics Panel",
        "location": "Room C"
      },
      {
        "day": "Day 1: June 12, 2025",
        "time": "14:00 - 15:30",
        "event": "Seminar: Cybersecurity in 2025",
        "location": "Room A"
      },
      {
        "day": "Day 2: June 13, 2025",
        "time": "10:00 - 11:30",
        "event": "Deep Dive: Rust for Backend Systems",
        "location": "Room B"
      },
      {
        "day": "Day 2: June 13, 2025",
        "time": "11:30 - 11:45",
        "event": "Transit Buffer",
        "location": "15 Minutes"
      },
      {
        "day": "Day 2: June 13, 2025",
        "time": "11:45 - 13:15",
        "event": "Networking Brunch: Startups & VCs",
        "location": "Garden Terrace"
      },
      {
        "day": "Day 2: June 13, 2025",
        "time": "14:00 - 16:00",
        "event": "Interactive Lab: Frontend Performance",
        "location": "Room D"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "hero_image",
        "itinerary_header_stack",
        "itinerary_table",
        "room_b_highlight_h3",
        "room_b_reminder_text",
        "quick_actions_h3",
        "quick_actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Global Tech Summit 2025: Berlin",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This technical itinerary for Berlin focuses on Generative AI, Vector Databases, and Cybersecurity, with specific highlights for sessions located in Room B."
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Brandenburger_Tor_abends.jpg/1200px-Brandenburger_Tor_abends.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "itinerary_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "itinerary_h2",
        "calendar_icon"
      ]
    },
    "itinerary_h2": {
      "type": "Text",
      "props": {
        "text": "Structured Event Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "calendar_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary_data",
        "columns": [
          {
            "key": "day",
            "label": "Day"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "event",
            "label": "Event"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "event",
        "highlightColumns": [
          "location"
        ]
      },
      "children": []
    },
    "room_b_highlight_h3": {
      "type": "Text",
      "props": {
        "text": "Room B Highlight",
        "variant": "h3"
      },
      "children": []
    },
    "room_b_reminder_text": {
      "type": "Text",
      "props": {
        "text": "Meeting Reminder: You have a meeting scheduled in Room B immediately following the sessions on both days. Please ensure you are packed and ready to transition promptly."
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "download_slides_button",
        "venue_map_button"
      ]
    },
    "download_slides_button": {
      "type": "Button",
      "props": {
        "label": "Download Slides"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://globaltech-berlin.com/sessions/slides"
          }
        }
      },
      "children": []
    },
    "venue_map_button": {
      "type": "Button",
      "props": {
        "label": "Venue Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://globaltech-berlin.com/venue/map"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "summit_program_button",
        "berlin_travel_button"
      ]
    },
    "summit_program_button": {
      "type": "Button",
      "props": {
        "label": "Summit Program",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://globaltech-berlin.com/agenda"
          }
        }
      },
      "children": []
    },
    "berlin_travel_button": {
      "type": "Button",
      "props": {
        "label": "Berlin Business Travel",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitberlin.de/en/business-travel"
          }
        }
      },
      "children": []
    }
  }
}
